sys_script_client.script:
/**
 * 销假结束时间 变更校验
 * 功能：确保销假结束日期 & 时间 必须在请假的时间范围内
 */
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    // 页面加载中 或 未输入值时，不执行校验
    if (isLoading || newValue === '') {
        return;
    }

    // 清空表单上所有错误提示
    g_form.clearMessages();

    // 获取当前销假结束的 日期 和 时间
    var eDate = g_form.getValue('cancel_end_date');
    var eTime = g_form.getValue('cancel_end_time');

    // 获取请假开始、结束时间（显示值）
    var leaveStartFull = g_form.getDisplayValue('leave_start_time');
    var leaveEndFull   = g_form.getDisplayValue('leave_end_time');

    // 截取请假开始、结束的 日期部分（yyyy-MM-dd）
    var leaveStartDate = leaveStartFull.split(' ')[0];
    var leaveEndDate   = leaveEndFull.split(' ')[0];

    // 未选择销假结束日期，不继续校验
    if (!eDate) return;

    // ===================== 校验1：销假结束日期必须在请假日期范围内 =====================
    if (eDate < leaveStartDate || eDate > leaveEndDate) {
        g_form.addErrorMessage('销假结束日期必须在请假日期内！');
        return;
    }

    // ===================== 校验2：填写了时间，则校验完整时间范围 =====================
    if (eTime) {
        // 拼接销假结束完整时间：日期 + 时间
        var cancelEnd = new Date(eDate + ' ' + eTime);
        // 转换请假开始、结束时间为日期对象
        var leaveStart = new Date(leaveStartFull);
        var leaveEnd   = new Date(leaveEndFull);

        // 判断销假结束时间是否超出请假时间范围
        if (cancelEnd < leaveStart || cancelEnd > leaveEnd) {
            g_form.addErrorMessage('销假结束时间不在请假时间范围内！');
        }
    }
}
